      "content": "const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const rootDir = path.resolve(__dirname, '../../..');
const depMapPath = path.join(rootDir, 'ChatMachines/GeminiSupervisor/dependency-map.json');

if (!fs.existsSync(depMapPath)) {
  console.error(`Dependency map not found: ${depMapPath}`);
  process.exit(1);
}

const depMap = JSON.parse(fs.readFileSync(depMapPath, 'utf8'));
const registry = depMap.truth_readable_registry || {};
let updatedCount = 0;

for (const [docId, config] of Object.entries(registry)) {
  const canonicalFullPath = path.join(rootDir, config.canonical_path);
  const readerFullPath = path.join(rootDir, config.stable_reader_path);

  if (!fs.existsSync(canonicalFullPath)) {
    console.warn(`Canonical source does not exist: ${config.canonical_path}`);
    continue;
  }

  const rawContent = fs.readFileSync(canonicalFullPath, 'utf8');
  const sourceSha256 = crypto.createHash('sha256').update(rawContent, 'utf8').digest('hex');

  let items = [];
  if (config.format === 'json') {
    const parsed = JSON.parse(rawContent);
    if (Array.isArray(parsed)) {
      items = parsed.map((val, idx) => ({
        index: idx,
        type: 'json_array_element',
        value: val
      }));
    } else if (parsed && typeof parsed === 'object') {
      items = Object.keys(parsed).map((key, idx) => ({
        index: idx,
        type: 'json_property',
        key: key,
        value: parsed[key]
      }));
    } else {
      items = [{
        index: 0,
        type: 'json_primitive',
        value: parsed
      }];
    }
  } else {
    const rawLines = rawContent.split(/\r?\n/);
    let currentTopic = null;
    let currentChunk = [];
    let chunkIndex = 0;

    const flushChunk = () => {
      if (currentChunk.length > 0) {
        items.push({
          index: chunkIndex++,
          type: 'text_paragraph',
          topic: currentTopic,
          text: currentChunk.join('\n')
        });
        currentChunk = [];
      }
    };

    for (const line of rawLines) {
      if (line.trim().startsWith('#')) {
        flushChunk();
        currentTopic = line.trim();
        items.push({
          index: chunkIndex++,
          type: 'heading',
          topic: currentTopic,
          text: line
        });
      } else if (line.trim() === '') {
        flushChunk();
      } else {
        currentChunk.push(line);
      }
    }
    flushChunk();
  }

  const stablePayload = {
    doc_id: docId,
    canonical_path: config.canonical_path,
    source_sha256: sourceSha256,
    generated_at: new Date().toISOString(),
    items: items
  };

  const serialized = JSON.stringify(stablePayload, null, 2) + '\n';
  let existingSerialized = null;
  if (fs.existsSync(readerFullPath)) {
    existingSerialized = fs.readFileSync(readerFullPath, 'utf8');
  }

  if (existingSerialized !== serialized) {
    fs.mkdirSync(path.dirname(readerFullPath), { recursive: true });
    fs.writeFileSync(readerFullPath, serialized, 'utf8');
    console.log(`Updated stable reader for [${docId}] -> ${config.stable_reader_path}`);
    updatedCount++;
  }
}

console.log(`Stable reader sync complete. ${updatedCount} file(s) updated.`);
