    {
      "path": "ChatMachines/GeminiSupervisor/scripts/truth-challenge-engine.js",
      "purpose": "Workflow-only CSPRNG seed generator, active projection emitter, snapshot storer, and strict zero-mutation-on-fail / restore-on-fail verifier",
      "content": "const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const rootDir = path.resolve(__dirname, '../../..');
const depMapPath = path.join(rootDir, 'ChatMachines/GeminiSupervisor/dependency-map.json');
const selectorPath = path.join(rootDir, 'ChatMachines/GeminiSupervisor/truth-selector.json');
const statusPath = path.join(rootDir, 'ChatMachines/GeminiSupervisor/truth-status.json');
const activeProjectionsDir = path.join(rootDir, 'ChatMachines/GeminiSupervisor/active-projections');
const snapshotsDir = path.join(rootDir, '.truth_challenge/snapshots');

function readJson(p) {
  return JSON.parse(fs.readFileSync(p, 'utf8'));
}

function writeJson(p, obj) {
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, JSON.stringify(obj, null, 2) + '\n', 'utf8');
}

function generateSeed() {
  return crypto.randomBytes(16).toString('hex');
}

function createChallenge() {
  const selector = readJson(selectorPath);
  const depMap = readJson(depMapPath);
  const registry = depMap.truth_readable_registry || {};

  const selectedIds = Object.keys(selector).filter(k => selector[k] === true);
  if (selectedIds.length === 0) {
    console.log('No documents selected for truth reading challenge.');
    return;
  }

  for (const docId of selectedIds) {
    if (!registry[docId]) {
      throw new Error(`Rejected unauthorized selector id: ${docId}`);
    }
  }

  const challengeId = 'tc_' + crypto.randomBytes(8).toString('hex');
  fs.mkdirSync(snapshotsDir, { recursive: true });
  fs.mkdirSync(activeProjectionsDir, { recursive: true });

  for (const docId of selectedIds) {
    const reg = registry[docId];
    const stableReaderPath = path.join(rootDir, reg.stable_reader_path);
    if (!fs.existsSync(stableReaderPath)) {
      throw new Error(`Stable reader not found at ${reg.stable_reader_path}. Sync required.`);
    }
    const stableData = readJson(stableReaderPath);
    const sourceItems = stableData.items || [];

    const seededItems = [];
    const totalItems = sourceItems.length;
    const seedSpacing = Math.max(1, Math.floor(totalItems / 4));

    let seedCounter = 0;
    for (let i = 0; i < totalItems; i++) {
      seededItems.push(sourceItems[i]);
      if ((i % seedSpacing === 0 && seedCounter < 5) || i === totalItems - 1) {
        const seedVal = generateSeed();
        seededItems.push({
          type: 'truth_seed',
          id: `${docId}_seed_${seedCounter++}`,
          value: seedVal,
          proof_slot: ' '.repeat(seedVal.length)
        });
      }
    }

    const activeProjection = {
      doc_id: docId,
      challenge_id: challengeId,
      canonical_path: reg.canonical_path,
      source_sha256: stableData.source_sha256,
      submitted_seeds: [],
      items: seededItems
    };

    const projectionPath = path.join(activeProjectionsDir, `${docId}.active-projection.json`);
    const snapshotPath = path.join(snapshotsDir, `${docId}.seeded-snapshot.json`);

    writeJson(projectionPath, activeProjection);
    writeJson(snapshotPath, activeProjection);
  }

  const challengeMeta = {
    challenge_id: challengeId,
    selected_docs: selectedIds,
    created_at: new Date().toISOString()
  };
  writeJson(path.join(snapshotsDir, 'meta.json'), challengeMeta);

  const statusData = {
    status: 'AWAITING_WORKER_EVIDENCE',
    active_challenge_id: challengeId,
    active_docs: selectedIds,
    last_outcome: null,
    timestamp: new Date().toISOString()
  };
  writeJson(statusPath, statusData);
  console.log(`Seeded challenge ${challengeId} created for docs: ${selectedIds.join(', ')}`);
}

function verifyChallenge() {
  const metaPath = path.join(snapshotsDir, 'meta.json');
  if (!fs.existsSync(metaPath)) {
    console.log('No active challenge snapshot exists to verify.');
    process.exit(0);
  }

  const meta = readJson(metaPath);
  const selectedDocs = meta.selected_docs;
  let allPassed = true;
  const failureReasons = [];

  for (const docId of selectedDocs) {
    const projectionPath = path.join(activeProjectionsDir, `${docId}.active-projection.json`);
    const snapshotPath = path.join(snapshotsDir, `${docId}.seeded-snapshot.json`);

    if (!fs.existsSync(projectionPath)) {
      allPassed = false;
      failureReasons.push(`Missing active projection for ${docId}`);
      continue;
    }

    const activeData = readJson(projectionPath);
    const snapshotData = readJson(snapshotPath);

    if (activeData.doc_id !== snapshotData.doc_id ||
        activeData.challenge_id !== snapshotData.challenge_id ||
        activeData.canonical_path !== snapshotData.canonical_path ||
        activeData.source_sha256 !== snapshotData.source_sha256) {
      allPassed = false;
      failureReasons.push(`Immutable header metadata corrupted in ${docId}`);
      continue;
    }

    const expectedItems = snapshotData.items;
    const submittedItems = activeData.items;

    if (!Array.isArray(submittedItems) || submittedItems.length !== expectedItems.length) {
      allPassed = false;
      failureReasons.push(`Item length mismatch in ${docId}`);
      continue;
    }

    const expectedSeeds = [];
    let itemsMatch = true;
    for (let i = 0; i < expectedItems.length; i++) {
      const exp = expectedItems[i];
      const sub = submittedItems[i];

      if (exp.type === 'truth_seed') {
        expectedSeeds.push(exp.value);
        if (sub.type !== 'truth_seed' || sub.id !== exp.id || sub.value !== exp.value) {
          itemsMatch = false;
          break;
        }
        const requiredProof = '0'.repeat(exp.value.length);
        if (sub.proof_slot !== requiredProof) {
          itemsMatch = false;
          break;
        }
      } else {
        if (JSON.stringify(exp) !== JSON.stringify(sub)) {
          itemsMatch = false;
          break;
        }
      }
    }

    if (!itemsMatch) {
      allPassed = false;
      failureReasons.push(`Content, seed, or proof_slot tamper in items array for ${docId}`);
      continue;
    }

    const submittedSeeds = Array.isArray(activeData.submitted_seeds) ? [...activeData.submitted_seeds] : null;
    if (!submittedSeeds) {
      allPassed = false;
      failureReasons.push(`submitted_seeds is not an array for ${docId}`);
      continue;
    }

    if (submittedSeeds.length !== expectedSeeds.length) {
      allPassed = false;
      failureReasons.push(`submitted_seeds count mismatch for ${docId}`);
      continue;
    }

    const sortExpected = [...expectedSeeds].sort();
    const sortSubmitted = submittedSeeds.sort();
    for (let i = 0; i < sortExpected.length; i++) {
      if (sortExpected[i] !== sortSubmitted[i]) {
        allPassed = false;
        failureReasons.push(`submitted_seeds content mismatch for ${docId}`);
        break;
      }
    }
  }

  if (allPassed) {
    console.log('VERIFICATION_RESULT=PASS');
    const selector = readJson(selectorPath);
    for (const k of Object.keys(selector)) {
      selector[k] = false;
    }
    writeJson(selectorPath, selector);

    if (fs.existsSync(activeProjectionsDir)) {
      fs.rmSync(activeProjectionsDir, { recursive: true, force: true });
    }
    if (fs.existsSync(snapshotsDir)) {
      fs.rmSync(snapshotsDir, { recursive: true, force: true });
    }

    const statusData = {
      status: 'PASS',
      active_challenge_id: null,
      active_docs: [],
      last_outcome: `PASS: Verified ${selectedDocs.join(', ')}`,
      timestamp: new Date().toISOString()
    };
    writeJson(statusPath, statusData);
  } else {
    console.log('VERIFICATION_RESULT=FAIL: ' + failureReasons.join('; '));
    for (const docId of selectedDocs) {
      const projectionPath = path.join(activeProjectionsDir, `${docId}.active-projection.json`);
      const snapshotPath = path.join(snapshotsDir, `${docId}.seeded-snapshot.json`);
      if (fs.existsSync(snapshotPath)) {
        fs.copyFileSync(snapshotPath, projectionPath);
      }
    }
    const statusData = {
      status: 'FAIL_RESTORED',
      active_challenge_id: meta.challenge_id,
      active_docs: selectedDocs,
      last_outcome: 'FAIL: worker edits failed validation; projections restored to original seeded state',
      timestamp: new Date().toISOString()
    };
    writeJson(statusPath, statusData);
  }
}

const command = process.argv[2];
if (command === 'create') {
  createChallenge();
} else if (command === 'verify') {
  verifyChallenge();
} else {
  console.error(`Unknown command: ${command}`);
  process.exit(1);
}
